CREATE TABLE "analistas" (
    "idAnalista"        int           GENERATED BY DEFAULT AS IDENTITY,
    "cedulaAnalista"     varchar(10)   NOT NULL,
    "nombreAnalista"     varchar(100)  NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkAnalista" PRIMARY KEY ("idAnalista"),
    CONSTRAINT "uqAnalistaCedula" UNIQUE ("cedulaAnalista"),
    CONSTRAINT "ckAnalistaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "parametros" (
    "idParametro"          int           GENERATED BY DEFAULT AS IDENTITY,
    "codigoParametro"       varchar(10)   NOT NULL,
    "nombreParametro"       varchar(100)  NOT NULL,
    "valorParametro"        numeric(10,4) NOT NULL,
    "fechaVigenciaDesde"   date          NOT NULL,
    "fechaVigenciaHasta"   date,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkParametro" PRIMARY KEY ("idParametro"),
    CONSTRAINT "uqParametroVigencia" UNIQUE ("codigoParametro", "fechaVigenciaDesde"),
    CONSTRAINT "ckParametroCodigo" CHECK ("codigoParametro" LIKE 'PAR-%'),
    CONSTRAINT "ckParametroVigencia" CHECK ("fechaVigenciaHasta" IS NULL OR "fechaVigenciaHasta" > "fechaVigenciaDesde"),
    CONSTRAINT "ckParametroAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "tramosCartera" (
    "idTramo"               int           GENERATED BY DEFAULT AS IDENTITY,
    "numeroTramo"            int           NOT NULL,
    "diasMoraDesde"         int           NOT NULL,
    "diasMoraHasta"         int         ,
    "estadoCartera"          varchar(10)   NOT NULL,
    "devengaIngresos"        boolean       NOT NULL,
    "tratamientoMora"        varchar(20)   NOT NULL,
    "porcentajeProvision"    numeric(5,4)  NOT NULL,
    "fechaVigenciaDesde"    date          NOT NULL,
    "fechaVigenciaHasta"    date,
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkTramoCartera" PRIMARY KEY ("idTramo"),
    CONSTRAINT "uqTramoVigencia" UNIQUE ("numeroTramo", "fechaVigenciaDesde"),
    CONSTRAINT "ckTramoEstado" CHECK ("estadoCartera" IN ('POR_VENCER', 'VENCIDA', 'EN_LITIGIO', 'CASTIGADA')),
    CONSTRAINT "ckTramoMora" CHECK ("tratamientoMora" IN ('NO_APLICA', 'SE_CALCULA', 'CUENTAS_DE_ORDEN', 'DEJA_DE_ACUMULARSE')),
    CONSTRAINT "ckTramoProvision" CHECK ("porcentajeProvision" BETWEEN 0 AND 1),
    CONSTRAINT "ckTramoRango" CHECK ("diasMoraHasta" IS NULL OR "diasMoraHasta" >= "diasMoraDesde"),
    CONSTRAINT "ckTramoVigencia" CHECK ("fechaVigenciaHasta" IS NULL OR "fechaVigenciaHasta" > "fechaVigenciaDesde"),
    CONSTRAINT "ckTramoCarteraAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "cierresDia" (
    "idCierre"          int           GENERATED BY DEFAULT AS IDENTITY,
    "fechaNegocio"       date          NOT NULL,
    "estadoCierre"       varchar(10)   NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkCierreDia" PRIMARY KEY ("idCierre"),
    CONSTRAINT "uqCierreFecha" UNIQUE ("fechaNegocio"),
    CONSTRAINT "ckCierreEstado" CHECK ("estadoCierre" IN ('PENDIENTE', 'EN_PROCESO', 'COMPLETADO', 'FALLIDO')),
    CONSTRAINT "ckCierreDiaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "ejecucionesEtapa" (
    "idEjecucion"           int           GENERATED BY DEFAULT AS IDENTITY,
    "idCierre"              int           NOT NULL,
    "numeroEtapa"            int           NOT NULL,
    "numeroIntento"          int           NOT NULL,
    "estadoEtapa"            varchar(10)   NOT NULL,
    "fechaHoraInicio"       timestamp      NOT NULL,
    "fechaHoraFin"          timestamp,
    "registrosProcesados"    int            NOT NULL,
    "mensajeError"           varchar(500),
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkEjecucionEtapa" PRIMARY KEY ("idEjecucion"),
    CONSTRAINT "uqEjecucionIntento" UNIQUE ("idCierre", "numeroEtapa", "numeroIntento"),
    CONSTRAINT "fkEjecucionCierre" FOREIGN KEY ("idCierre") REFERENCES "cierresDia" ("idCierre"),
    CONSTRAINT "ckEjecucionEtapa" CHECK ("numeroEtapa" BETWEEN 1 AND 6),
    CONSTRAINT "ckEjecucionEstado" CHECK ("estadoEtapa" IN ('EN_PROCESO', 'EXITOSA', 'FALLIDA')),
    CONSTRAINT "ckEjecucionError" CHECK ("estadoEtapa" <> 'FALLIDA' OR "mensajeError" IS NOT NULL),
    CONSTRAINT "ckEjecucionEtapaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "solicitudes" (
    "idSolicitud"                   int           GENERATED BY DEFAULT AS IDENTITY,
    "idCliente"                     int           NOT NULL,
    "sistemaAmortizacion"            varchar(7)    NOT NULL,
    "idAnalista"                    int,
    "montoSolicitado"                numeric(10,2) NOT NULL,
    "plazoMeses"                     int           NOT NULL,
    "destinoCredito"                 varchar(20)   NOT NULL,
    "ingresosMensuales"              numeric(10,2) NOT NULL,
    "gastosMensuales"                numeric(10,2) NOT NULL,
    "fechaSolicitud"                 date          NOT NULL,
    "fechaHoraRegistro"             timestamp      NOT NULL,
    "cuotaEvaluacionReferencial"    numeric(10,2) NOT NULL,
    "teaAsignada"                    numeric(5,4),
    "cuotaEvaluacionDefinitiva"     numeric(10,2),
    "estadoSolicitud"                varchar(20)   NOT NULL,
    "fechaResolucion"                date,
    "motivoRechazo"                  varchar(200),
    "usuarioCreacion"               varchar(50)   NOT NULL,
    "fechaCreacion"                 timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"           varchar(50),
    "fechaModificacion"             timestamp,
    CONSTRAINT "pkSolicitud" PRIMARY KEY ("idSolicitud"),
    CONSTRAINT "fkSolicitudAnalista" FOREIGN KEY ("idAnalista") REFERENCES "analistas" ("idAnalista"),
    CONSTRAINT "ckSolicitudMonto" CHECK ("montoSolicitado" > 0),
    CONSTRAINT "ckSolicitudSistema" CHECK ("sistemaAmortizacion" IN ('FRANCES', 'ALEMAN')),
    CONSTRAINT "ckSolicitudPlazo" CHECK ("plazoMeses" > 0),
    CONSTRAINT "ckSolicitudDestino" CHECK ("destinoCredito" IN ('BIENES_DURADEROS', 'SALUD', 'EDUCACION', 'VIAJE', 'OTRO')),
    CONSTRAINT "ckSolicitudIngresos" CHECK ("ingresosMensuales" >= 0 AND "gastosMensuales" >= 0),
    CONSTRAINT "ckSolicitudCuotas" CHECK ("cuotaEvaluacionReferencial" > 0
                                      AND ("cuotaEvaluacionDefinitiva" IS NULL OR "cuotaEvaluacionDefinitiva" > 0)),
    CONSTRAINT "ckSolicitudEstado" CHECK ("estadoSolicitud" IN ('REGISTRADA', 'RECHAZADA', 'APROBADA')),
    CONSTRAINT "ckSolicitudDefinitiva" CHECK (("teaAsignada" IS NULL) = ("cuotaEvaluacionDefinitiva" IS NULL)
                                         AND ("estadoSolicitud" = 'APROBADA') = ("teaAsignada" IS NOT NULL)),
    CONSTRAINT "ckSolicitudTea" CHECK ("teaAsignada" IS NULL OR "teaAsignada" > 0),
    CONSTRAINT "ckSolicitudMotivo" CHECK (("estadoSolicitud" = 'RECHAZADA') = ("motivoRechazo" IS NOT NULL)),
    CONSTRAINT "ckSolicitudResolucion" CHECK (("estadoSolicitud" = 'REGISTRADA') = ("fechaResolucion" IS NULL)),
    CONSTRAINT "ckSolicitudAnalista" CHECK ("estadoSolicitud" <> 'APROBADA' OR "idAnalista" IS NOT NULL),
    CONSTRAINT "ckSolicitudAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "operaciones" (
    "idOperacion"                   int           GENERATED BY DEFAULT AS IDENTITY,
    "idSolicitud"                   int           NOT NULL,
    "idCliente"                     int           NOT NULL,
    "cedulaCliente"                  varchar(10)   NOT NULL,
    "sistemaAmortizacion"            varchar(10)    NOT NULL,
    "numeroOperacion"                varchar(20)   NOT NULL,
    "montoAprobado"                  numeric(10,2) NOT NULL,
    "teaAsignada"                    numeric(5,4)  NOT NULL,
    "plazoMeses"                     int           NOT NULL,
    "seguroMensual"                  numeric(10,2) NOT NULL,
    "contribucionSolca"              numeric(10,2) NOT NULL,
    "montoNeto"                      numeric(10,2) NOT NULL,
    "cuentaDestino"                  varchar(20)   NOT NULL,
    "fechaDesembolso"                date          NOT NULL,
    "estadoInstruccionDesembolso"   varchar(10)    NOT NULL,
    "estadoCartera"                  varchar(10)   NOT NULL,
    "saldoCapital"                   numeric(10,2) NOT NULL,
    "diasMora"                       int           NOT NULL DEFAULT 0,
    "usuarioCreacion"               varchar(50)   NOT NULL,
    "fechaCreacion"                 timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"           varchar(50),
    "fechaModificacion"             timestamp,
    CONSTRAINT "pkOperacion" PRIMARY KEY ("idOperacion"),
    CONSTRAINT "uqOperacionNumero" UNIQUE ("numeroOperacion"),
    CONSTRAINT "uqOperacionSolicitud" UNIQUE ("idSolicitud"),
    CONSTRAINT "fkOperacionSolicitud" FOREIGN KEY ("idSolicitud") REFERENCES "solicitudes" ("idSolicitud"),
    CONSTRAINT "ckOperacionCedula" CHECK ("cedulaCliente" ~ '^[0-9]{10}$'),
    CONSTRAINT "ckOperacionSistema" CHECK ("sistemaAmortizacion" IN ('FRANCES', 'ALEMAN')),
    CONSTRAINT "ckOperacionInstruccion" CHECK ("estadoInstruccionDesembolso" IN ('PENDIENTE', 'ENTREGADA')),
    CONSTRAINT "ckOperacionEstado" CHECK ("estadoCartera" IN ('POR_VENCER', 'VENCIDA', 'EN_LITIGIO', 'CASTIGADA', 'CANCELADA')),
    CONSTRAINT "ckOperacionCondiciones" CHECK ("montoAprobado" > 0 AND "teaAsignada" > 0 AND "plazoMeses" > 0
                                           AND "seguroMensual" >= 0 AND "contribucionSolca" >= 0),
    CONSTRAINT "ckOperacionNeto" CHECK ("montoNeto" = "montoAprobado" - "contribucionSolca"),
    CONSTRAINT "ckOperacionSaldo" CHECK ("saldoCapital" >= 0 AND "saldoCapital" <= "montoAprobado" AND "diasMora" >= 0),
    CONSTRAINT "ckOperacionCancelada" CHECK ("estadoCartera" <> 'CANCELADA' OR "saldoCapital" = 0),
    CONSTRAINT "ckOperacionAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "cuotas" (
    "idCuota"               int           GENERATED BY DEFAULT AS IDENTITY,
    "idOperacion"           int           NOT NULL,
    "numeroCuota"            int           NOT NULL,
    "fechaVencimiento"       date          NOT NULL,
    "valorCapital"           numeric(10,2) NOT NULL,
    "valorInteres"           numeric(10,2) NOT NULL,
    "valorSeguro"            numeric(10,2) NOT NULL,
    "totalCuota"             numeric(10,2) GENERATED ALWAYS AS ("valorCapital" + "valorInteres" + "valorSeguro") STORED,
    "ajusteDevengoInteres"  numeric(10,2),
    "saldoCapitalPosterior" numeric(10,2) NOT NULL,
    "seguroPagado"          numeric(10,2) NOT NULL DEFAULT 0,
    "moraPagada"            numeric(10,2) NOT NULL DEFAULT 0,
    "interesPagado"         numeric(10,2) NOT NULL DEFAULT 0,
    "capitalPagado"         numeric(10,2) NOT NULL DEFAULT 0,
    "moraAcumulada"         numeric(10,4) NOT NULL DEFAULT 0,
    "estadoCuota"           varchar(15)   NOT NULL DEFAULT 'PENDIENTE',
    "fechaPago"             date,
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkCuota" PRIMARY KEY ("idCuota"),
    CONSTRAINT "uqCuotaNumero" UNIQUE ("idOperacion", "numeroCuota"),
    CONSTRAINT "fkCuotaOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "ckCuotaNumero" CHECK ("numeroCuota" > 0),
    CONSTRAINT "ckCuotaValores" CHECK ("valorCapital" >= 0 AND "valorInteres" >= 0 AND "valorSeguro" >= 0),
    CONSTRAINT "ckCuotaPagado" CHECK ("seguroPagado" BETWEEN 0 AND "valorSeguro" AND "interesPagado" BETWEEN 0 AND "valorInteres"
                                   AND "capitalPagado" BETWEEN 0 AND "valorCapital" AND "moraPagada" >= 0 AND "moraAcumulada" >= 0
                                   AND "saldoCapitalPosterior" >= 0),
    CONSTRAINT "ckCuotaEstado" CHECK ("estadoCuota" = CASE
        WHEN "seguroPagado" + "interesPagado" + "capitalPagado" = 0 THEN 'PENDIENTE'
        WHEN "seguroPagado" = "valorSeguro" AND "interesPagado" = "valorInteres" AND "capitalPagado" = "valorCapital" THEN 'PAGADA'
        ELSE 'PAGO_PARCIAL' END),
    CONSTRAINT "ckCuotaFechaPago" CHECK (("estadoCuota" = 'PAGADA') = ("fechaPago" IS NOT NULL)),
    CONSTRAINT "ckCuotaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "cuentasContables" (
    "idCuentaContable"  int           GENERATED BY DEFAULT AS IDENTITY,
    "codigoCuenta"       varchar(25)   NOT NULL,
    "nombreCuenta"       varchar(100)  NOT NULL,
    "tipoCuenta"         varchar(10)    NOT NULL,
    "naturalezaCuenta"   varchar(10)    NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkCuentaContable" PRIMARY KEY ("idCuentaContable"),
    CONSTRAINT "uqCuentaCodigo" UNIQUE ("codigoCuenta"),
    CONSTRAINT "ckCuentaTipo" CHECK ("tipoCuenta" IN ('ACTIVO', 'PASIVO', 'INGRESO', 'GASTO', 'ORDEN')),
    CONSTRAINT "ckCuentaNaturaleza" CHECK ("naturalezaCuenta" IN ('DEUDORA', 'ACREEDORA')),
    CONSTRAINT "ckCuentaContableAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "asientosContables" (
    "idAsiento"             int           GENERATED BY DEFAULT AS IDENTITY,
    "idOperacion"           int,
    "fechaAsiento"           date          NOT NULL,
    "tipoAsiento"            varchar(20)   NOT NULL,
    "idCuentaDebito"        int           NOT NULL,
    "idCuentaCredito"       int           NOT NULL,
    "montoAsiento"           numeric(10,2) NOT NULL,
    "claveIdempotencia"      varchar(60)   NOT NULL,
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkAsientoContable" PRIMARY KEY ("idAsiento"),
    CONSTRAINT "uqAsientoClave" UNIQUE ("claveIdempotencia"),
    CONSTRAINT "fkAsientoOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "fkAsientoDebito" FOREIGN KEY ("idCuentaDebito") REFERENCES "cuentasContables" ("idCuentaContable"),
    CONSTRAINT "fkAsientoCredito" FOREIGN KEY ("idCuentaCredito") REFERENCES "cuentasContables" ("idCuentaContable"),
    CONSTRAINT "ckAsientoTipo" CHECK ("tipoAsiento" IN ('DESEMBOLSO', 'DEVENGO', 'DEVENGO_SUSPENSO', 'AJUSTE_DEVENGO', 'MORA',
                                                       'RECLASIFICACION', 'PAGO', 'PROVISION', 'CASTIGO', 'RECUPERACION')),
    CONSTRAINT "ckAsientoCuentas" CHECK ("idCuentaDebito" <> "idCuentaCredito"),
    CONSTRAINT "ckAsientoMonto" CHECK ("montoAsiento" > 0),
    CONSTRAINT "ckAsientoContableAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "devengosDiarios" (
    "idDevengo"         int           GENERATED BY DEFAULT AS IDENTITY,
    "idOperacion"       int           NOT NULL,
    "fechaDevengo"       date          NOT NULL,
    "interesDevengado"   numeric(10,4) NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkDevengoDiario" PRIMARY KEY ("idDevengo"),
    CONSTRAINT "uqDevengoDia" UNIQUE ("idOperacion", "fechaDevengo"),
    CONSTRAINT "fkDevengoOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "fkDevengoCierre" FOREIGN KEY ("fechaDevengo") REFERENCES "cierresDia" ("fechaNegocio"),
    CONSTRAINT "ckDevengoInteres" CHECK ("interesDevengado" >= 0),
    CONSTRAINT "ckDevengoDiarioAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "morasDiarias" (
    "idMora"            int           GENERATED BY DEFAULT AS IDENTITY,
    "idCuota"           int           NOT NULL,
    "fechaMora"          date          NOT NULL,
    "interesMora"        numeric(10,4) NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkMoraDiaria" PRIMARY KEY ("idMora"),
    CONSTRAINT "uqMoraDia" UNIQUE ("idCuota", "fechaMora"),
    CONSTRAINT "fkMoraCuota" FOREIGN KEY ("idCuota") REFERENCES "cuotas" ("idCuota"),
    CONSTRAINT "fkMoraCierre" FOREIGN KEY ("fechaMora") REFERENCES "cierresDia" ("fechaNegocio"),
    CONSTRAINT "ckMoraInteres" CHECK ("interesMora" >= 0),
    CONSTRAINT "ckMoraDiariaAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "fotosCartera" (
    "idOperacion"                   int           NOT NULL,
    "fechaFoto"                      date          NOT NULL,
    "idTramo"                       int           NOT NULL,
    "estadoCartera"                  varchar(10)   NOT NULL,
    "diasMora"                       int           NOT NULL,
    "saldoCapital"                   numeric(10,2) NOT NULL,
    "valorProvision"                 numeric(10,2) NOT NULL,
    "interesDevengadoAcumulado"     numeric(10,2) NOT NULL,
    "interesMoraAcumulado"          numeric(10,2) NOT NULL,
    "usuarioCreacion"               varchar(50)   NOT NULL,
    "fechaCreacion"                 timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"           varchar(50),
    "fechaModificacion"             timestamp,
    CONSTRAINT "pkFotoCartera" PRIMARY KEY ("idOperacion", "fechaFoto"),
    CONSTRAINT "fkFotoOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "fkFotoCierre" FOREIGN KEY ("fechaFoto") REFERENCES "cierresDia" ("fechaNegocio"),
    CONSTRAINT "fkFotoTramo" FOREIGN KEY ("idTramo") REFERENCES "tramosCartera" ("idTramo"),
    CONSTRAINT "ckFotoEstado" CHECK ("estadoCartera" IN ('POR_VENCER', 'VENCIDA', 'EN_LITIGIO', 'CASTIGADA')),
    CONSTRAINT "ckFotoValores" CHECK ("diasMora" >= 0 AND "saldoCapital" >= 0 AND "valorProvision" >= 0
                                      AND "interesDevengadoAcumulado" >= 0 AND "interesMoraAcumulado" >= 0),
    CONSTRAINT "ckFotoCarteraAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "cambiosEstadoOperacion" (
    "idCambioEstado"   int           GENERATED BY DEFAULT AS IDENTITY,
    "idOperacion"       int           NOT NULL,
    "fechaCambio"        date          NOT NULL,
    "estadoAnterior"     varchar(10)   NOT NULL,
    "estadoNuevo"        varchar(10)   NOT NULL,
    "diasMora"           int           NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkCambioEstadoOperacion" PRIMARY KEY ("idCambioEstado"),
    CONSTRAINT "uqCambioDia" UNIQUE ("idOperacion", "fechaCambio"),
    CONSTRAINT "fkCambioOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "fkCambioCierre" FOREIGN KEY ("fechaCambio") REFERENCES "cierresDia" ("fechaNegocio"),
    CONSTRAINT "ckCambioEstados" CHECK ("estadoAnterior" IN ('POR_VENCER', 'VENCIDA', 'EN_LITIGIO', 'CASTIGADA')
                                    AND "estadoNuevo" IN ('POR_VENCER', 'VENCIDA', 'EN_LITIGIO', 'CASTIGADA', 'CANCELADA')
                                    AND "estadoAnterior" <> "estadoNuevo"
                                    AND ("estadoAnterior" <> 'CASTIGADA' OR "estadoNuevo" = 'CANCELADA')),
    CONSTRAINT "ckCambioDias" CHECK ("diasMora" >= 0),
    CONSTRAINT "ckCambioEstadoOperacionAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "codigosValidacion" (
    "idCodigoValidacion"    int           GENERATED BY DEFAULT AS IDENTITY,
    "codigoValidacion"       varchar(10)    NOT NULL,
    "nivelValidacion"        varchar(10)    NOT NULL,
    "descripcionValidacion"  varchar(200)  NOT NULL,
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkCodigoValidacion" PRIMARY KEY ("idCodigoValidacion"),
    CONSTRAINT "uqCodigoValidacion" UNIQUE ("codigoValidacion"),
    CONSTRAINT "ckValidacionNivel" CHECK ("nivelValidacion" IN ('ARCHIVO', 'REGISTRO')),
    CONSTRAINT "ckCodigoValidacionAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "archivosRecaudacion" (
    "idArchivo"             int           GENERATED BY DEFAULT AS IDENTITY,
    "fechaCarga"             date          NOT NULL,
    "nombreArchivo"          varchar(30)   NOT NULL,
    "hashSha256"             varchar(64),
    "fechaProcesoArchivo"   date,
    "fechaHoraGeneracion"   timestamp,
    "totalRegistros"         int          ,
    "montoTotalArchivo"     numeric(12,2),
    "estadoArchivo"          varchar(10)    NOT NULL,
    "codigoRechazo"          varchar(10),
    "usuarioCreacion"       varchar(50)   NOT NULL,
    "fechaCreacion"         timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"   varchar(50),
    "fechaModificacion"     timestamp,
    CONSTRAINT "pkArchivoRecaudacion" PRIMARY KEY ("idArchivo"),
    CONSTRAINT "fkArchivoCierre" FOREIGN KEY ("fechaCarga") REFERENCES "cierresDia" ("fechaNegocio"),
    CONSTRAINT "fkArchivoCodigo" FOREIGN KEY ("codigoRechazo") REFERENCES "codigosValidacion" ("codigoValidacion"),
    CONSTRAINT "ckArchivoHash" CHECK ("hashSha256" IS NULL OR "hashSha256" ~ '^[0-9a-fA-F]{64}$'),
    CONSTRAINT "ckArchivoEstado" CHECK ("estadoArchivo" IN ('PROCESADO', 'RECHAZADO')),
    CONSTRAINT "ckArchivoRechazo" CHECK (("estadoArchivo" = 'RECHAZADO') = ("codigoRechazo" IS NOT NULL)
                                     AND ("codigoRechazo" IS NULL OR "codigoRechazo" LIKE 'ARC-%')),
    CONSTRAINT "ckArchivoProcesado" CHECK ("estadoArchivo" <> 'PROCESADO'
                                       OR ("hashSha256" IS NOT NULL AND "fechaProcesoArchivo" IS NOT NULL
                                           AND "totalRegistros" IS NOT NULL AND "montoTotalArchivo" IS NOT NULL)),
    CONSTRAINT "ckArchivoRecaudacionAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "registrosRecaudacion" (
    "idRegistro"        int           GENERATED BY DEFAULT AS IDENTITY,
    "idArchivo"         int           NOT NULL,
    "numeroSecuencial"   int           NOT NULL,
    "uuidTransaccion"    uuid,
    "numeroOperacion"    varchar(20),
    "cedulaCliente"      varchar(10),
    "montoPagado"        numeric(10,2),
    "fechaHoraCobro"    timestamp,
    "canalPago"          varchar(10),
    "referenciaPago"     varchar(100),
    "lineaOriginal"      varchar(500),
    "estadoRegistro"     varchar(10)    NOT NULL,
    "codigoRechazo"      varchar(10),
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkRegistroRecaudacion" PRIMARY KEY ("idRegistro"),
    CONSTRAINT "uqRegistroSecuencial" UNIQUE ("idArchivo", "numeroSecuencial"),
    CONSTRAINT "fkRegistroArchivo" FOREIGN KEY ("idArchivo") REFERENCES "archivosRecaudacion" ("idArchivo"),
    CONSTRAINT "fkRegistroCodigo" FOREIGN KEY ("codigoRechazo") REFERENCES "codigosValidacion" ("codigoValidacion"),
    CONSTRAINT "ckRegistroEstado" CHECK ("estadoRegistro" IN ('APLICADO', 'RECHAZADO', 'DUPLICADO')),
    CONSTRAINT "ckRegistroCodigo" CHECK (("estadoRegistro" = 'APLICADO' AND ("codigoRechazo" IS NULL OR "codigoRechazo" = 'REG-007'))
                                      OR ("estadoRegistro" = 'DUPLICADO' AND "codigoRechazo" = 'REG-002')
                                      OR ("estadoRegistro" = 'RECHAZADO' AND "codigoRechazo" IS NOT NULL AND "codigoRechazo" LIKE 'REG-%' AND "codigoRechazo" NOT IN ('REG-002', 'REG-007'))),
    CONSTRAINT "ckRegistroCanal" CHECK ("canalPago" IS NULL OR "canalPago" IN ('VEN', 'WEB', 'DEB', 'TRF')),
    CONSTRAINT "ckRegistroRecaudacionAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "pagos" (
    "idPago"            int           GENERATED BY DEFAULT AS IDENTITY,
    "idOperacion"       int           NOT NULL,
    "idRegistro"        int,
    "idAnalista"        int,
    "origenPago"         varchar(25)   NOT NULL,
    "fechaPago"          date          NOT NULL,
    "montoRecibido"      numeric(10,2),
    "modalidadAbono"     varchar(15),
    "excedenteDevuelto"  numeric(10,2) NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkPago" PRIMARY KEY ("idPago"),
    CONSTRAINT "uqPagoRegistro" UNIQUE ("idRegistro"),
    CONSTRAINT "fkPagoOperacion" FOREIGN KEY ("idOperacion") REFERENCES "operaciones" ("idOperacion"),
    CONSTRAINT "fkPagoRegistro" FOREIGN KEY ("idRegistro") REFERENCES "registrosRecaudacion" ("idRegistro"),
    CONSTRAINT "fkPagoAnalista" FOREIGN KEY ("idAnalista") REFERENCES "analistas" ("idAnalista"),
    CONSTRAINT "ckPagoOrigen" CHECK ("origenPago" IN ('ARCHIVO_RECAUDACION', 'ABONO_EXTRAORDINARIO', 'CANCELACION_ANTICIPADA')),
    CONSTRAINT "ckPagoFuente" CHECK (("origenPago" = 'ARCHIVO_RECAUDACION') = ("idRegistro" IS NOT NULL)
                                 AND ("idRegistro" IS NULL) = ("montoRecibido" IS NOT NULL)),
    CONSTRAINT "ckPagoAnalista" CHECK (("origenPago" = 'ARCHIVO_RECAUDACION') = ("idAnalista" IS NULL)),
    CONSTRAINT "ckPagoModalidad" CHECK (("origenPago" = 'ABONO_EXTRAORDINARIO') = ("modalidadAbono" IS NOT NULL)
                                    AND ("modalidadAbono" IS NULL OR "modalidadAbono" IN ('DISMINUIR_CUOTA', 'DISMINUIR_PLAZO'))),
    CONSTRAINT "ckPagoMontos" CHECK (("montoRecibido" IS NULL OR "montoRecibido" > 0) AND "excedenteDevuelto" >= 0),
    CONSTRAINT "ckPagoAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE TABLE "detallesPago" (
    "idDetallePago"    int           GENERATED BY DEFAULT AS IDENTITY,
    "idPago"            int           NOT NULL,
    "idCuota"           int,
    "aplicadoSeguro"     numeric(10,2) NOT NULL,
    "aplicadoMora"       numeric(10,2) NOT NULL,
    "aplicadoInteres"    numeric(10,2) NOT NULL,
    "aplicadoCapital"    numeric(10,2) NOT NULL,
    "usuarioCreacion"      varchar(50)   NOT NULL,
    "fechaCreacion"        timestamp     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "usuarioModificacion"  varchar(50),
    "fechaModificacion"    timestamp,
    CONSTRAINT "pkDetallePago" PRIMARY KEY ("idDetallePago"),
    CONSTRAINT "fkDetallePago" FOREIGN KEY ("idPago") REFERENCES "pagos" ("idPago"),
    CONSTRAINT "fkDetalleCuota" FOREIGN KEY ("idCuota") REFERENCES "cuotas" ("idCuota"),
    CONSTRAINT "uqDetalleCuota" UNIQUE ("idPago", "idCuota"),
    CONSTRAINT "ckDetalleValores" CHECK ("aplicadoSeguro" >= 0 AND "aplicadoMora" >= 0 AND "aplicadoInteres" >= 0 AND "aplicadoCapital" >= 0
                                         AND "aplicadoSeguro" + "aplicadoMora" + "aplicadoInteres" + "aplicadoCapital" > 0),
    CONSTRAINT "ckDetallePagoAuditoria" CHECK (("usuarioModificacion" IS NULL) = ("fechaModificacion" IS NULL)
        AND ("fechaModificacion" IS NULL OR "fechaModificacion" >= "fechaCreacion"))
);

CREATE UNIQUE INDEX "uqCierreAbierto" ON "cierresDia" ((true)) WHERE "estadoCierre" <> 'COMPLETADO';
CREATE INDEX "ixSolicitudCliente" ON "solicitudes" ("idCliente");
CREATE INDEX "ixSolicitudBandeja" ON "solicitudes" ("estadoSolicitud", "fechaHoraRegistro");
CREATE INDEX "ixOperacionCliente" ON "operaciones" ("idCliente");
CREATE INDEX "ixOperacionCedula" ON "operaciones" ("cedulaCliente");
CREATE INDEX "ixOperacionEstado" ON "operaciones" ("estadoCartera");
CREATE INDEX "ixCuotaPendiente" ON "cuotas" ("idOperacion", "fechaVencimiento") WHERE "estadoCuota" <> 'PAGADA';
CREATE INDEX "ixCuotaVencimiento" ON "cuotas" ("fechaVencimiento");
CREATE INDEX "ixFotoFecha" ON "fotosCartera" ("fechaFoto", "idTramo");
CREATE UNIQUE INDEX "uqArchivoNombreHash" ON "archivosRecaudacion" ("nombreArchivo", "hashSha256") WHERE "estadoArchivo" = 'PROCESADO';
CREATE INDEX "ixRegistroUuid" ON "registrosRecaudacion" ("uuidTransaccion");
CREATE UNIQUE INDEX "uqRegistroUuidAplicado" ON "registrosRecaudacion" ("uuidTransaccion") WHERE "estadoRegistro" = 'APLICADO';
CREATE INDEX "ixPagoOperacion" ON "pagos" ("idOperacion", "fechaPago");
CREATE INDEX "ixPagoAnalista" ON "pagos" ("idAnalista");
CREATE INDEX "ixDetallePago" ON "detallesPago" ("idPago");
CREATE INDEX "ixDetalleCuota" ON "detallesPago" ("idCuota");
CREATE INDEX "ixAsientoFecha" ON "asientosContables" ("fechaAsiento");
CREATE INDEX "ixAsientoOperacion" ON "asientosContables" ("idOperacion");
